package org.mockito.internal.util.reflection;

import java.io.*;
import java.lang.reflect.Field;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class GenericMaster_getGenericType_TriageGen0Test {

    private GenericMaster genericMaster;

    @Before
    public void setUp() {
        genericMaster = new GenericMaster();
    }





    @Test
    public void testGetGenericType_ActualTypeIsClass() throws NoSuchFieldException {
        Field field = mock(Field.class);
        ParameterizedType parameterizedType = mock(ParameterizedType.class);

        when(field.getGenericType()).thenReturn(parameterizedType);
        // getActualTypeArguments()[-1] means the last element
        when(parameterizedType.getActualTypeArguments()).thenReturn(new Type[]{String.class});

        Class<?> result = genericMaster.getGenericType(field);

        assertEquals(String.class, result);
    }




}

package org.mockito.internal.util.reflection;

import java.io.*;
import java.lang.reflect.Field;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class GenericMaster_getGenericType_TriageGen0Test {

    private GenericMaster genericMaster;

    @Before
    public void setUp() {
        genericMaster = new GenericMaster();
    }







    @Test
    public void testGetGenericType_ActualTypeIsNestedParameterizedType() throws NoSuchFieldException {
        Field field = mock(Field.class);
        ParameterizedType outerType = mock(ParameterizedType.class);
        ParameterizedType innerType = mock(ParameterizedType.class);

        when(field.getGenericType()).thenReturn(outerType);
        // Mocking the last element of the array to be the inner parameterized type
        when(outerType.getActualTypeArguments()).thenReturn(new Type[]{innerType});
        when(innerType.getRawType()).thenReturn(List.class);

        Class<?> result = genericMaster.getGenericType(field);

        assertEquals(List.class, result);
    }


}

package org.mockito.internal.util.reflection;

